opts('dt-city',D.CITY,S.city);opts('dt-hw',D.HW,S.hw);opts('dt-cool',D.COOL,S.cool);opts('dt-ups',D.UPS,S.ups);opts('dt-red',D.RED,S.red);opts('dt-pwr',D.PWR,S.pwr);opts('dt-ws',D.WS,S.ws);opts('dt-model',D.MODEL,S.model);opts('dt-prec',D.PREC,S.prec);
function rejOpts(){const list=D.REJFOR(S.cool);if(!list.includes(S.rej))S.rej=list[0];$('dt-rej').innerHTML=list.map(k=>`<option value="${k}"${k===S.rej?' selected':''}>${esc(D.REJ[k].n)}</option>`).join('')}
const SEL=['city','hw','cool','rej','ups','red','pwr','ws','model','prec','dist','tr'],NUM={mw:'dt-mw',uT:'dt-uT',uI:'dt-uI',uG:'dt-uG',train:'dt-train',inf:'dt-inf',tsa:'dt-tsa',coc:'dt-coc'},NSEL={wc:'dt-wc',batch:'dt-batch',tpp:'dt-tpp',mfu:'dt-mfu'};
SEL.forEach(k=>$('dt-'+k).addEventListener('change',e=>{S[k]=e.target.value;if(k==='cool'){rejOpts();applyCoolDefaults()}if(k==='hw')hwDefaults();run()}));
Object.entries(NUM).forEach(([k,id])=>$(id).addEventListener('input',e=>{S[k]=+e.target.value;run()}));
