function blowKL(){if(!R||!R.ok)return 0;if(['wcc','twr'].includes(S.rej)||(R.c.liq&&S.rej==='twr')){const mk=R.siteKL,ev=mk/1.005*(S.coc-1)/S.coc;return Math.max(0,mk-ev)}if(S.rej==='wcch'||S.rej==='adi'||S.cool==='iec')return R.siteKL*.09;return 0}
