const svgW=(inner,h)=>`<div class="dt-svgw"><svg viewBox="0 0 680 ${h||230}" class="dt-sch" role="img"><defs>${['p','h','w','c','a'].map(k=>`<marker id="dtm2-${k}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" class="mk-${k}"/></marker>`).join('')}</defs>${inner}</svg></div>`;
const steps=a=>`<ol class="dt-steps">${a.map(x=>`<li>${x}</li>`).join('')}</ol>`;
const kv=a=>`<div class="dt-kv">${a.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div>`;
