function altR(cool){const list=D.REJFOR(cool);const rej=list.includes(S.rej)?S.rej:(cool==='dlc'||cool==='im1'||cool==='im2')?'dry':list[0];const hw=D.HW[S.hw].ok.includes(cool)&&D.HW[S.hw].kw<=D.COOL[cool].max?S.hw:(D.COOL[cool].liq?'h100':D.COOL[cool].max>=41&&D.HW.h100.ok.includes(cool)?'h100':D.COOL[cool].max>=18&&D.HW.l40s.ok.includes(cool)?'l40s':'cpu');return D.compute(Object.assign({},S,{cool,rej,hw}))}
